 public static void Run(){var s=new Snapshot{Id=Guid.NewGuid(),Owner=Guid.NewGuid()};Authority.Seed(s.Settings);s.Settings["moduleMaster"]=new JsonArray(new JsonObject{["id"]="fin",["code"]="FIN",["name"]="Finance",["active"]=true});s.Settings["activityMaster"]=new JsonArray(new JsonObject{["id"]="a",["code"]="ACT",["name"]="Work",["typeId"]="implementation",["active"]=true});s.Members["pm"]=new JsonObject{["id"]="pm",["name"]="Planner",["role"]="Project manager",["active"]=true};var project=new JsonObject{["id"]="p",["code"]="P",["name"]="Project",["stageType"]="implementation",["projectManager"]="pm",["lead"]="pm",["companyCount"]=2,["companyWiseProjectTrackingRequired"]=false,["modules"]=new JsonObject{["Finance"]="pm"},["moduleTeams"]=new JsonObject{["Finance"]=new JsonArray("pm")},["companies"]=new JsonArray(new JsonObject{["id"]="c1",["name"]="Alpha",["code"]="A",["modules"]=new JsonObject()},new JsonObject{["id"]="c2",["name"]="Beta",["code"]="B",["modules"]=new JsonObject{["Finance"]="pm"}})};s.Records["project:p"]=project;var policy=new Policy(s,new AppUser(s.Owner,s.Id,"","",true,null,false,false,0,null,""));
