 var input=Input(false);input["companyId"]="outside-project";var preview=ImplementationPlanImports.Validate(s,policy,input);Check(J.N(preview,"invalidCount")==0&&J.S(preview["items"]![0]!["payload"],"companyId")=="c1"&&!preview["columns"]!.AsArray().Any(c=>c?.ToString()=="Company"),"Project-wide import has no company requirement and uses project modules/internal link");var copy=s.Copy();ImplementationPlanImports.Apply(copy,new Policy(copy,new AppUser(copy.Owner,copy.Id,"","",true,null,false,false,0,null,"")),input);Check(copy.Records.Values.Any(t=>J.S(t,"implementationPlanRowId")!=""),"Project-wide import still creates linked work");
