 JsonObject Generic(bool withCompany,string value=""){var cols=SpreadsheetImports.PlanColumns.Where(c=>withCompany||c!="Company").ToArray();var vals=new Dictionary<string,string>{{"Plan Reference","REF"},{"Project Code","P"},{"Company",value},{"Module","Finance"},{"Activity Code","ACT"},{"Consultant","pm"},{"Planned Start",J.Today.ToString("yyyy-MM-dd")},{"Planned Finish",J.Today.ToString("yyyy-MM-dd")},{"Planned Hours","4"},{"Priority","Medium"},{"Notes",""}};return new JsonObject{["selectedProjectId"]="p",["headers"]=new JsonArray(cols.Select(c=>(JsonNode?)JsonValue.Create(c)).ToArray()),["rows"]=new JsonArray(new JsonArray(cols.Select(c=>(JsonNode?)JsonValue.Create(vals[c])).ToArray()))};}
 Check(J.N(SpreadsheetImports.Validate(s,policy,"project-plan",Generic(false)),"invalidCount")==1,"Generic enabled import requires company");Check(J.N(SpreadsheetImports.Validate(s,policy,"project-plan",Generic(true,"Beta")),"invalidCount")==0,"Generic valid company accepted");project["companyWiseProjectTrackingRequired"]=false;var generic=SpreadsheetImports.Validate(s,policy,"project-plan",Generic(false));Check(J.N(generic,"invalidCount")==0&&!generic["columns"]!.AsArray().Any(c=>c?.ToString()=="Company"),"Generic disabled import accepts no company heading/details");
 project["companyWiseProjectTrackingRequired"]=true;var weeklyLookup=SpreadsheetImports.Validate(s,policy,"project-plan",Generic(true,"Beta"),true);Check(weeklyLookup["items"]![0]!["display"]![2]!.ToString()=="Beta","Weekly lookup display retains names for editable preview compatibility");
 // Exercise the real task save policy, including tasks that carry actual/calendar/timesheet allocations.
 var allocationState=s.Copy();var allocationProject=allocationState.Records["project:p"];allocationProject["companies"]![0]!["modules"]=new JsonObject();var owner57=new Policy(allocationState,new AppUser(allocationState.Owner,allocationState.Id,"","",true,null,false,false,0,null,""));
 JsonObject Task57(string id,string company)=>new(){["id"]=id,["project"]="p",["companyId"]=company,["module"]="Finance",["typeId"]="implementation",["title"]="Work",["activityId"]="a",["assignee"]="pm",["plannedStart"]=J.Today.ToString("yyyy-MM-dd"),["plannedFinish"]=J.Today.ToString("yyyy-MM-dd"),["plannedSessions"]=.5,["status"]="To do",["completion"]=0,["sessions"]=new JsonArray(),["history"]=new JsonArray(),["allocations"]=new JsonArray(new JsonObject{["id"]=id+"-alloc",["assignee"]="pm",["date"]=J.Today.ToString("yyyy-MM-dd"),["plannedHours"]=2m,["typeId"]="implementation",["workMode"]="Offsite",["chargeType"]="Internal",["status"]="Planned",["actualHistory"]=new JsonArray()})};
 void Save57(Policy who,JsonObject task)=>who.Apply(new JsonObject{["records"]=new JsonArray(new JsonObject{["kind"]="task",["id"]=J.S(task,"id"),["payload"]=task.DeepClone()})});
 Deny(()=>Save57(owner57,Task57("missing57","")));Deny(()=>Save57(owner57,Task57("foreign57","foreign")));Deny(()=>Save57(owner57,Task57("wrong-module57","c1")));Save57(owner57,Task57("company57","c2"));Check(J.S(allocationState.Records["task:company57"],"companyId")=="c2","Task allocation saves the selected company");
