 var retained=J.Clone(allocationState.Records["task:company57"]);var extra=J.Clone(J.A(retained,"allocations").First());extra["id"]="additional57";retained["allocations"]!.AsArray().Add(extra);Save57(owner57,retained);Check(J.S(allocationState.Records["task:company57"],"companyId")=="c2","New allocation of historical project-level task preserves existing company link");
