 var monday=J.Today.AddDays(-(((int)J.Today.DayOfWeek+6)%7));
 JsonObject Weekly57(bool company,string value=""){var columns=WeeklySpreadsheetImports.Columns.Where(c=>company||c!="Company").ToArray();var values=new Dictionary<string,string>{{"Visit Reference","WEEK57"},{"Activity Date",monday.ToString("yyyy-MM-dd")},{"Project Code","P"},{"Company",value},{"Module","Finance"},{"Activity Code","ACT"},{"Consultant","pm"},{"Start Time","20:00"},{"End Time","21:00"},{"Work Mode","Onsite"},{"Hours Classification","Client"},{"Notes","Weekly test"},{"Existing Task ID",""}};return new JsonObject{["weekStart"]=monday.ToString("yyyy-MM-dd"),["headers"]=new JsonArray(columns.Select(c=>(JsonNode?)JsonValue.Create(c)).ToArray()),["rows"]=new JsonArray(new JsonArray(columns.Select(c=>(JsonNode?)JsonValue.Create(values[c])).ToArray()))};}
 Check(J.N(WeeklySpreadsheetImports.Validate(allocationState,owner57,Weekly57(false)),"invalidCount")==1,"Tracked weekly allocation requires a company value");Check(J.N(WeeklySpreadsheetImports.Validate(allocationState,owner57,Weekly57(true,"B")),"invalidCount")==0,"Tracked weekly allocation accepts registered company code");allocationProject["companyWiseProjectTrackingRequired"]=false;Check(J.N(WeeklySpreadsheetImports.Validate(allocationState,owner57,Weekly57(false)),"invalidCount")==0,"Project-wide weekly allocation needs no Company header or value");
 Console.WriteLine("PASS v57: task save policy enforces company/module scope; project-wide/self/weekly allocations require no company selection; existing company links remain stable.");
 Console.WriteLine("PASS v55: company-aware/no-company imports, master references, project modules, legacy context, per-company duplicates, internal links and invalid batch rejection.");}
